export const getAppliancesProducts = (): Product[] => APPLIANCES_PRODUCTS;

export const getFeaturedAppliancesProducts = (): Product[] => 
  APPLIANCES_PRODUCTS.filter(product => product.featured);

export const getAppliancesProductsByBadge = (badge: string): Product[] =>
  APPLIANCES_PRODUCTS.filter(product => product.badge === badge);

export const getAppliancesProductsByPriceRange = (min: number, max: number): Product[] =>
  APPLIANCES_PRODUCTS.filter(product => product.price >= min && product.price <= max);
